"""Text helpers shared by the claim form and the ledger bridge."""
import unicodedata

_SPACES = {"\t", "\n", "\r", "\x0b", "\x0c", " ", "　"}


def normalize(text):
    """NFC-normalize, turn odd whitespace into plain spaces, collapse runs."""
    if text is None:
        return ""
    text = unicodedata.normalize("NFC", str(text))
    out = []
    for ch in text:
        if ch in _SPACES:
            ch = " "
        elif unicodedata.category(ch) == "Cc":
            continue
        if ch == " " and out and out[-1] == " ":
            continue
        out.append(ch)
    return "".join(out).strip()


def clip_chars(text, limit):
    """Cut text to at most `limit` characters (never splits a character)."""
    if limit <= 0:
        return ""
    if len(text) <= limit:
        return text
    return text[:limit].rstrip()


def display_width(text):
    """Terminal/report column width: East Asian wide characters count as 2."""
    width = 0
    for ch in text:
        width += 2 if unicodedata.east_asian_width(ch) in ("W", "F") else 1
    return width


def pad_display(text, width):
    """Pad (or cut) text so that it occupies exactly `width` report columns."""
    out, used = [], 0
    for ch in text:
        w = display_width(ch)
        if used + w > width:
            break
        out.append(ch)
        used += w
    return "".join(out) + " " * (width - used)
"""Turns an approved expense claim into a ledger entry."""
from hbexpense.models import LedgerEntry
from hbexpense.util.text import clip_chars, normalize


def compose_memo(claim):
    """Memo shown to the finance team: claim id, claimant, what it was for."""
    parts = [claim.claim_id, claim.claimant, claim.description]
    return normalize(" ".join(p for p in parts if p))


def build_entry(claim, settings):
    account = settings.accounts.get(claim.category)
    if account is None:
        raise ValueError(f"no ledger account for category {claim.category}")
    memo = clip_chars(compose_memo(claim), settings.ledger_memo_chars)
    return LedgerEntry(
        account=account,
        amount=claim.amount,
        date=claim.spent_on,
        ref=claim.claim_id,
        memo=memo,
    )
import unittest

from hbexpense.util.text import clip_chars, display_width, normalize, pad_display


class TextTest(unittest.TestCase):
    def test_normalize_collapses_whitespace_and_controls(self):
        self.assertEqual(normalize(" a\t\tb　c\x07 "), "a b c")
        self.assertEqual(normalize(None), "")

    def test_normalize_composes_hangul(self):
        decomposed = "한"  # 한 as jamo
        self.assertEqual(normalize(decomposed), "한")

    def test_clip_chars_counts_characters(self):
        self.assertEqual(clip_chars("가나다라마", 3), "가나다")
        self.assertEqual(clip_chars("abc", 5), "abc")
        self.assertEqual(clip_chars("ab cd", 3), "ab")
        self.assertEqual(clip_chars("abc", 0), "")

    def test_display_width(self):
        self.assertEqual(display_width("ab"), 2)
        self.assertEqual(display_width("가나"), 4)

    def test_pad_display(self):
        self.assertEqual(pad_display("가나다", 5), "가나 ")
        self.assertEqual(pad_display("ab", 4), "ab  ")


if __name__ == "__main__":
    unittest.main()
